/**
 * The mark this chapter stores, and the one validator both transports
 * import. The route handler and the Server Action are two doors onto the
 * same cookie, so the shape and the rules live here and are written once —
 * which is also the chapter's own point: the thing you actually had to
 * write is the rule, not the plumbing.
 *
 * A cookie is visitor-editable storage, so everything read back is parsed
 * like it was typed by a stranger, because it was.
 */

export const MARK_COOKIE = "playground-presses";
export const MAX_COUNT = 9999;
export const MAX_NOTE = 40;

export interface Mark {
  readonly count: number;
  readonly note: string;
}

export const EMPTY_MARK: Mark = { count: 0, note: "" };

export type NoteFailure = "empty" | "not-text" | "too-long";

export type NoteCheck =
  | { readonly ok: false; readonly reason: NoteFailure }
  | { readonly ok: true; readonly value: string };

const COUNT_PATTERN = /^\d{1,4}$/;

/** `decodeURIComponent` throws on a malformed escape; the note is visitor data. */
function decodeNote(raw: string): string {
  try {
    return decodeURIComponent(raw).slice(0, MAX_NOTE);
  } catch {
    return "";
  }
}

/**
 * Reads the cookie. Tolerates the bare-number format this chapter shipped
 * before it grew a note, so a returning visitor keeps their count.
 */
export function parseMark(raw: string | undefined): Mark {
  if (!raw) {
    return EMPTY_MARK;
  }
  const separator = raw.indexOf(":");
  const countPart = separator === -1 ? raw : raw.slice(0, separator);
  if (!COUNT_PATTERN.test(countPart)) {
    return EMPTY_MARK;
  }
  const count = Math.min(Number.parseInt(countPart, 10), MAX_COUNT);
  const note = separator === -1 ? "" : decodeNote(raw.slice(separator + 1));
  return { count, note };
}

export function serializeMark(mark: Mark): string {
  return `${mark.count}:${encodeURIComponent(mark.note)}`;
}

/**
 * The rule. Both transports call this before they write anything, which is
 * why the route handler's 400 and the action's error value say the same
 * thing about the same input.
 */
export function checkNote(raw: unknown): NoteCheck {
  if (typeof raw !== "string") {
    return { ok: false, reason: "not-text" };
  }
  const value = raw.trim();
  if (value.length === 0) {
    return { ok: false, reason: "empty" };
  }
  if (value.length > MAX_NOTE) {
    return { ok: false, reason: "too-long" };
  }
  return { ok: true, value };
}

export function nextMark(current: Mark, note: string): Mark {
  return { count: Math.min(current.count + 1, MAX_COUNT), note };
}
```

