import { type NextRequest, NextResponse } from "next/server";
import {
  checkNote,
  MARK_COOKIE,
  MAX_NOTE,
  nextMark,
  type NoteFailure,
  parseMark,
  serializeMark,
} from "../../[locale]/(playground)/mutation/note-cookie";

/**
 * The endpoint the mutation chapter's first arrangement really posts to.
 * It is not a strawman: it validates, it writes, and it answers correctly.
 * What it cannot do is re-render the page that called it, which is the
 * whole exhibit.
 *
 * It is also a real public door on this site, which is the chapter's own
 * argument — so it is method-restricted, capped, and writes nothing but
 * the caller's own cookie.
 */

const ONE_YEAR_SECONDS = 60 * 60 * 24 * 365;

const FAILURE_MESSAGES: Record<NoteFailure, string> = {
  empty: "note is empty",
  "not-text": "note must be a string",
  "too-long": `note is longer than ${MAX_NOTE} characters`,
};

function badRequest(error: string) {
  return NextResponse.json({ error, ok: false }, { status: 400 });
}

export async function POST(request: NextRequest) {
  let payload: unknown;
  try {
    payload = await request.json();
  } catch {
    return badRequest("body is not JSON");
  }

  const note = checkNote((payload as { note?: unknown } | null)?.note);
  if (!note.ok) {
    return badRequest(FAILURE_MESSAGES[note.reason]);
  }

  const mark = nextMark(
    parseMark(request.cookies.get(MARK_COOKIE)?.value),
    note.value
  );

  const response = NextResponse.json({
    count: mark.count,
    note: mark.note,
    ok: true,
  });
  response.cookies.set(MARK_COOKIE, serializeMark(mark), {
    httpOnly: true,
    maxAge: ONE_YEAR_SECONDS,
    path: "/",
    sameSite: "lax",
  });
  return response;
}

/** The other half of the tutorial's checklist, made true rather than quoted. */
export function GET() {
  return NextResponse.json(
    { error: "method not allowed", ok: false },
    { headers: { Allow: "POST" }, status: 405 }
  );
}
