```ts
/**
 * The three arrangements the deck walks — the journey a developer actually
 * takes, not a comparison table. The endpoint first, because that is where
 * the reader already lives; the refresh that rescues it, because that is
 * the fix they reach for; then the Server Action.
 *
 * `tripsFor` and `repaints` are the mechanism as data, so the panel's copy
 * can be checked against them rather than asserted by hand.
 */
export type Transport = "action" | "refresh" | "route";

/** Execution order, which is also deck order, left to right. */
export const TRANSPORT_ORDER: readonly Transport[] = [
  "route",
  "refresh",
  "action",
];

/** The believer's arrangement — where the instrument rests. */
export const DEFAULT_TRANSPORT: Transport = "route";

export function nextTransport(current: Transport): Transport | undefined {
  return TRANSPORT_ORDER[TRANSPORT_ORDER.indexOf(current) + 1];
}

export function isSpent(candidate: Transport, current: Transport): boolean {
  return TRANSPORT_ORDER.indexOf(candidate) < TRANSPORT_ORDER.indexOf(current);
}

/** Round trips one press costs. The refresh cannot start until the fetch resolves. */
export function tripsFor(transport: Transport): number {
  return transport === "refresh" ? 2 : 1;
}

/** Whether the page the reader is looking at ends up showing the new value. */
export function repaints(transport: Transport): boolean {
  return transport !== "route";
}
```

