```ts
import type { Transport } from "./transport";

/**
 * One press, drawn as the exchange it actually was.
 *
 * Every number here was measured at our own call sites or echoed back by
 * the server; nothing is patched into the browser's fetch and nothing is
 * simulated. The one fact we state rather than measure is the RSC
 * content-type, because reading response headers off a router refresh
 * would mean instrumenting the browser, and one honest sentence in the
 * seam costs less than that.
 *
 * `party` is the second channel design.md asks for: the same table read
 * as "who wrote this line". In the endpoint's arrangement every row is
 * the developer's. In the action's, one is.
 */

/** Stated, not measured — see the seam. Real: it is what RSC responses carry. */
export const RSC_CONTENT_TYPE = "text/x-component";

export type Party = "build" | "you";

export interface Trip {
  /** Server-echoed from `headers()` inside the action. Action trips only. */
  readonly actionId?: string;
  /** Measured off `res.headers`. JSON trips only. */
  readonly contentType?: string;
  readonly kind: "json" | "rsc";
  readonly method: "GET" | "POST";
  readonly ms: number;
  readonly path: string;
  /** The JSON body, one line. JSON trips only. */
  readonly summary?: string;
}

export interface Run {
  readonly note: string;
  readonly transport: Transport;
  readonly trips: readonly Trip[];
}

export interface ExchangeRow {
  readonly label: string;
  readonly party: Party;
  readonly value: string;
}

export interface Exchange {
  readonly down: readonly ExchangeRow[];
  readonly method: string;
  readonly ms: number;
  readonly path: string;
  readonly up: readonly ExchangeRow[];
}

/** A bar with nothing in it is still a bar — give the zero a mark. */
const MIN_FILL_PERCENT = 0.6;
/** Keeps a one-trip run from filling the whole track and reading as "slow". */
const AXIS_HEADROOM = 1.15;
const AXIS_FLOOR_MS = 200;
const ID_KEPT = 8;

export function shortActionId(id: string): string {
  return id.length > ID_KEPT ? `${id.slice(0, ID_KEPT)}…` : id;
}

export function totalMs(run: Run): number {
  return run.trips.reduce((sum, trip) => sum + trip.ms, 0);
}

export function axisMaxMs(run: Run): number {
  return Math.max(Math.round(totalMs(run) * AXIS_HEADROOM), AXIS_FLOOR_MS);
}

export function barPercent(ms: number, axisMax: number): number {
  const raw = axisMax > 0 ? (ms / axisMax) * 100 : 0;
  return Math.min(Math.max(raw, MIN_FILL_PERCENT), 100);
}

function jsonExchange(trip: Trip): Exchange {
  return {
    down: [
      { label: "status", party: "you", value: "200" },
      {
        label: "content-type",
        party: "you",
        value: trip.contentType ?? "application/json",
      },
      { label: "body", party: "you", value: trip.summary ?? "" },
    ],
    method: trip.method,
    ms: trip.ms,
    path: trip.path,
    up: [
      { label: "url", party: "you", value: trip.path },
      { label: "content-type", party: "you", value: "application/json" },
      { label: "body", party: "you", value: '{"note":"…"}' },
    ],
  };
}

function rscExchange(trip: Trip): Exchange {
  const up: ExchangeRow[] = [
    { label: "url", party: "build", value: trip.path },
  ];
  if (trip.actionId) {
    up.push({
      label: "next-action",
      party: "build",
      value: shortActionId(trip.actionId),
    });
    up.push({ label: "body", party: "you", value: "your form's fields" });
  }
  return {
    down: [
      { label: "status", party: "build", value: "200" },
      { label: "content-type", party: "build", value: RSC_CONTENT_TYPE },
      { label: "body", party: "build", value: "the page, re-rendered" },
    ],
    method: trip.method,
    ms: trip.ms,
    path: trip.path,
    up,
  };
}

export function toExchanges(run: Run): readonly Exchange[] {
  return run.trips.map((trip) =>
    trip.kind === "json" ? jsonExchange(trip) : rscExchange(trip)
  );
}
```

