"use server";

import { cookies, headers } from "next/headers";
import {
  checkNote,
  MARK_COOKIE,
  MAX_NOTE,
  nextMark,
  type NoteFailure,
  parseMark,
  serializeMark,
} from "./note-cookie";

const ONE_YEAR_SECONDS = 60 * 60 * 24 * 365;

const FAILURE_MESSAGES: Record<NoteFailure, string> = {
  empty: "note is empty",
  "not-text": "note must be a string",
  "too-long": `note is longer than ${MAX_NOTE} characters`,
};

export interface SaveResult {
  /**
   * The id the server actually received, read off the incoming request.
   * The panel shows this so the reader sees a real per-build identifier
   * they did not choose — server-observed, not a client guess.
   */
  readonly actionId: string;
  readonly error?: string;
  readonly ok: boolean;
}

/**
 * The entire backend of this chapter's third arrangement. Setting a cookie
 * in a Server Action makes Next.js re-render the current page and its
 * layouts on the server, so the specimen shows the new value without
 * anything here asking it to.
 *
 * Errors come back as a value, not as a status code. That is the contrast
 * the endpoint's 400 is there to make.
 */
export async function saveNote(
  _previous: SaveResult | null,
  formData: FormData
): Promise<SaveResult> {
  const requestHeaders = await headers();
  const actionId = requestHeaders.get("next-action") ?? "";

  const note = checkNote(formData.get("note"));
  if (!note.ok) {
    return { actionId, error: FAILURE_MESSAGES[note.reason], ok: false };
  }

  const jar = await cookies();
  const mark = nextMark(parseMark(jar.get(MARK_COOKIE)?.value), note.value);
  jar.set(MARK_COOKIE, serializeMark(mark), {
    httpOnly: true,
    maxAge: ONE_YEAR_SECONDS,
    path: "/",
    sameSite: "lax",
  });

  return { actionId, ok: true };
}
