import { cookies } from "next/headers";
import { MARK_COOKIE, parseMark } from "./note-cookie";

interface NoteValueProps {
  /** The seam's caption for the arrangement currently on the bench. */
  caption: string;
}

/**
 * A Server Component reading request data, which is why the page keeps it
 * behind Suspense — it cannot be baked into the shell, because the shell is
 * shared and your mark, tragically, is yours.
 *
 * This is the thing that does not move in the first arrangement. It renders
 * when the server renders the page, and an endpoint answering a fetch is
 * not that.
 */
export async function NoteValue({ caption }: NoteValueProps) {
  const jar = await cookies();
  const mark = parseMark(jar.get(MARK_COOKIE)?.value);

  return (
    <div className="flex flex-col gap-1">
      <p className="font-display font-medium text-4xl text-foreground tabular-nums tracking-tight sm:text-5xl">
        {mark.count}
        <span className="ml-3 font-normal text-lg text-muted-foreground tracking-normal">
          {mark.count === 1 ? "press" : "presses"}
