```tsx
import { cn } from "@repo/design-system/lib/utils";
import { PARTY_MARKS } from "./copy";
import {
  axisMaxMs,
  barPercent,
  type Exchange,
  type ExchangeRow,
  type Run,
  toExchanges,
  totalMs,
} from "./exchange";

/**
 * The two presentations of one press. The stage's `data-view` decides
 * which one has a size, so flipping the switch is a CSS change rather than
 * a re-run — the two drawings can never disagree about a number, because
 * they are the same run.
 */
export const PAGE_ONLY = "group-data-[view=network]/stage:hidden";
export const NETWORK_ONLY = "group-data-[view=page]/stage:hidden";

/** Three columns: what was sent, how long it took drawn, how long it took read. */
const TRACK_GRID = cn(
  "grid grid-cols-[minmax(0,1fr)_5rem] items-center gap-x-3 gap-y-1",
  "sm:grid-cols-[10rem_minmax(0,1fr)_5rem] sm:gap-y-0"
);

const TRACK_CELL = "order-3 col-span-2 sm:order-2 sm:col-span-1";
const READING_CELL = "order-2 text-right sm:order-3";

/**
 * One row of an exchange. The gutter mark is the second channel: the same
 * table read as "who wrote this line". A visitor who reads nothing else
 * can see that one arrangement's rows are all theirs and the other's
 * are not.
 */
function Row({ row }: { row: ExchangeRow }) {
  return (
    <div className="grid grid-cols-[7rem_minmax(0,1fr)] items-baseline gap-x-3 py-0.5">
      <span className="truncate font-mono text-muted-foreground text-xs">
        {row.label}
      </span>
      <span className="flex flex-wrap items-baseline gap-x-2 font-mono text-foreground/80 text-xs">
        <span className="truncate">{row.value}</span>
        <span
          className={cn(
            "text-[0.65rem]",
            row.party === "you"
              ? "text-(--color-hastoggle-orange)"
              : "text-muted-foreground/60"
          )}
        >
          {PARTY_MARKS[row.party]}
        </span>
      </span>
    </div>
  );
}

function ExchangeCard({
  axisMax,
  exchange,
}: {
  axisMax: number;
  exchange: Exchange;
}) {
  return (
    <div className="flex flex-col gap-2">
      <div className={TRACK_GRID}>
        <span className="order-1 truncate font-mono text-muted-foreground text-xs">
          {exchange.method} {exchange.path}
        </span>
        <span
          className={cn(
            "relative block h-7 overflow-hidden rounded-md border border-foreground/10 bg-muted/30",
            TRACK_CELL
          )}
        >
          <span
            className="absolute inset-y-0 left-0 bg-ht-cyan-500/30 dark:bg-ht-cyan-400/25"
            style={{ width: `${barPercent(exchange.ms, axisMax)}%` }}
          />
        </span>
        <span
          className={cn(
            "font-mono text-muted-foreground text-xs tabular-nums",
            READING_CELL
          )}
        >
          {exchange.ms} ms
        </span>
      </div>
      <div className="rounded-md border border-foreground/10 bg-muted/20 px-3 py-2">
        <p className="mb-1 font-mono text-[0.65rem] text-muted-foreground uppercase tracking-[0.2em]">
          sent
        </p>
        {exchange.up.map((row) => (
          <Row key={`${row.label}-${row.value}`} row={row} />
        ))}
        <p className="mt-2 mb-1 font-mono text-[0.65rem] text-muted-foreground uppercase tracking-[0.2em]">
          came back
        </p>
        {exchange.down.map((row) => (
          <Row key={`${row.label}-${row.value}`} row={row} />
        ))}
      </div>
    </div>
  );
}

/** The run, drawn as its exchange. Bars stack in time: two trips read twice as long. */
export function ExchangeBars({ run }: { run: Run | null }) {
  if (!run || run.trips.length === 0) {
    return (
      <p className="font-mono text-muted-foreground text-xs/5">
        press the button — nothing has gone over the wire yet
      </p>
    );
  }

  const axisMax = axisMaxMs(run);
  const exchanges = toExchanges(run);

  return (
    <div className="flex flex-col gap-4">
      {exchanges.map((exchange, index) => (
        <ExchangeCard
          axisMax={axisMax}
          exchange={exchange}
          key={`${exchange.method}-${exchange.path}-${index}`}
        />
      ))}
      <p className="font-mono text-muted-foreground text-xs tabular-nums">
        {exchanges.length === 1 ? "1 request" : `${exchanges.length} requests`}{" "}
        · {totalMs(run)} ms total
      </p>
    </div>
  );
}
