"use client";

import { useActionState, useCallback, useEffect, useRef, useState } from "react";
import { useRouter } from "next/navigation";
import { MarketingButton } from "../../components/marketing-button";
import { type SaveResult, saveNote } from "./actions";
import {
  NOTE_LABEL,
  NOTE_PLACEHOLDER,
  SUBMIT_LABEL,
  SUBMIT_PENDING_LABEL,
} from "./copy";
import type { Run, Trip } from "./exchange";
import type { Transport } from "./transport";

interface NoteFormProps {
  onRun: (run: Run) => void;
  onWorking: (working: boolean) => void;
  transport: Transport;
}

/**
 * The specimen's form. It stays in the panel body, not the deck: a form
 * wired to a Server Action is the lesson, and filing the subject under
 * controls would misrepresent it (design.md §4).
 *
 * Each arrangement dispatches for real. Nothing is simulated, and no
 * global fetch is patched — every duration is stamped around our own
 * call sites, and the action's id is read by the server and handed back.
 */
export function NoteForm({ onRun, onWorking, transport }: NoteFormProps) {
  const router = useRouter();
  const [note, setNote] = useState("");
  const [error, setError] = useState<string | null>(null);
  const [busy, setBusy] = useState(false);
  const [state, formAction, actionPending] = useActionState<
    SaveResult | null,
    FormData
  >(saveNote, null);

  // The refresh trip has no promise to await: router.refresh() returns
  // void and commits when the client has the new tree. The honest stamp
  // is the falling edge of the pending flag, so the pending run parks
  // here until that edge arrives.
  const pendingRefresh = useRef<{ startedAt: number; trips: Trip[] } | null>(
    null
  );
  const actionStartedAt = useRef<number | null>(null);

  const finish = useCallback(
    (trips: Trip[]) => {
      onRun({ note, transport, trips });
      onWorking(false);
      setBusy(false);
    },
    [note, onRun, onWorking, transport]
  );

  const postToEndpoint = useCallback(async (): Promise<{
    trip: Trip;
    failed: boolean;
  }> => {
    const startedAt = performance.now();
    const response = await fetch("/api/press", {
      body: JSON.stringify({ note }),
      headers: { "content-type": "application/json" },
      method: "POST",
    });
    const contentType = response.headers.get("content-type") ?? "";
    const payload = await response.json();
    const ms = Math.round(performance.now() - startedAt);
    return {
      failed: !response.ok,
      trip: {
        contentType: contentType.split(";")[0],
        kind: "json",
        method: "POST",
        ms,
        path: "/api/press",
        summary: JSON.stringify(payload),
      },
    };
  }, [note]);

  const handleSubmit = useCallback(
    async (event: React.FormEvent<HTMLFormElement>) => {
      if (transport === "action") {
        // Let the form post to the Server Action: useActionState owns it.
        actionStartedAt.current = performance.now();
        onWorking(true);
        return;
      }
      event.preventDefault();
      setError(null);
      setBusy(true);
      onWorking(true);

      const { failed, trip } = await postToEndpoint();
      if (failed) {
        const parsed = JSON.parse(trip.summary ?? "{}");
        setError(parsed.error ?? "the endpoint refused it");
      }

      if (transport === "route") {
        finish([trip]);
        return;
      }

      // The refresh cannot start until the fetch resolves. That is the
      // arrangement's whole cost, and it is why the bars stack.
      pendingRefresh.current = { startedAt: performance.now(), trips: [trip] };
      router.refresh();
    },
    [finish, onWorking, postToEndpoint, router, transport]
  );

  // The refresh's falling edge: the tree has committed, so stamp and report.
  useEffect(() => {
    const parked = pendingRefresh.current;
    if (!parked) {
      return;
    }
    const id = window.setTimeout(() => {
      pendingRefresh.current = null;
      finish([
        ...parked.trips,
        {
          kind: "rsc",
          method: "GET",
          ms: Math.round(performance.now() - parked.startedAt),
          path: window.location.pathname,
        },
      ]);
    }, 0);
    return () => window.clearTimeout(id);
  });

  // The action's falling edge: useActionState has the server's reply.
  useEffect(() => {
    if (actionPending || actionStartedAt.current === null || !state) {
      return;
    }
    const ms = Math.round(performance.now() - actionStartedAt.current);
    actionStartedAt.current = null;
    setError(state.ok ? null : (state.error ?? null));
    finish([
      {
        actionId: state.actionId,
        kind: "rsc",
        method: "POST",
        ms,
        path: window.location.pathname,
      },
    ]);
  }, [actionPending, finish, state]);

  const pending = busy || actionPending;

  return (
    <form
      action={transport === "action" ? formAction : undefined}
      className="flex flex-col gap-3"
      onSubmit={handleSubmit}
    >
      <label
        className="font-mono text-muted-foreground text-xs/5"
        htmlFor="mutation-note"
      >
        {NOTE_LABEL}
      </label>
      <div className="flex flex-wrap items-center gap-3">
        <input
          className="min-w-0 flex-1 rounded-md border border-foreground/15 bg-background px-3 py-2 font-mono text-sm outline-none focus-visible:ring-2 focus-visible:ring-ht-cyan-500/50"
          id="mutation-note"
          name="note"
          onChange={(event) => setNote(event.target.value)}
          placeholder={NOTE_PLACEHOLDER}
          type="text"
          value={note}
        />
        <MarketingButton disabled={pending} type="submit">
          {pending ? SUBMIT_PENDING_LABEL : SUBMIT_LABEL}
        </MarketingButton>
      </div>
      <p className="min-h-5 font-mono text-(--color-hastoggle-orange) text-xs/5">
        {error}
      </p>
    </form>
  );
}
```

**Known wrinkle to resolve while implementing:** the refresh effect above runs
on every render and uses a `setTimeout(0)` to land after the committed tree.
If browser verification shows the stamp landing before the specimen visibly
updates, switch to watching a `useTransition` pending flag around
`router.refresh()` — wrap the call in `startTransition` and stamp on the
`isPending` true→false edge. Both are honest measurements of "when the client
had the new tree"; pick whichever actually corresponds to the repaint, and
