} from "./copy";
import type { Run } from "./exchange";
import { ExchangeBars, NETWORK_ONLY, PAGE_ONLY } from "./exchange-bars";
import { NoteForm } from "./note-form";
import {
  nextTransport,
  TRANSPORT_ORDER,
  type Transport,
} from "./transport";

// The outline variant's `disabled:` look re-expressed for `aria-disabled`,
// so a locked step stays focusable and keyboard users keep their place.
// Same trick as the boundary and stream decks.
const LOCKED_LOOK = cn(
  "aria-disabled:bg-transparent aria-disabled:opacity-40",
  "aria-disabled:cursor-not-allowed aria-disabled:hover:bg-transparent"
);

const ARMED_LOOK = "ring-ht-cyan-700/50 dark:ring-ht-cyan-400/50";

function StepMark({ n }: { n: string }) {
  return (
    <span
      aria-hidden="true"
      className="mr-2 select-none font-mono text-muted-foreground text-xs"
    >
      {n}
    </span>
  );
}

interface MutationPanelProps {
  references: React.ReactNode;
  /** The Server Component reading the cookie, handed across as a slot. */
  specimen: React.ReactNode;
}

/**
 * The client owner of the mutation instrument. The gauge is wired to the
 * whole press, not to the navigation: in the refresh arrangement it has to
 * stay amber across both trips, because the second one is the arrangement's
 * entire cost and a gauge that went quiet between them would be the panel's
 * first lie.
 *
 * No reset in the chrome: rewinding this bench means running the first
 * arrangement, and deck step one already is that button (design.md §1).
 */
export function MutationPanel({ references, specimen }: MutationPanelProps) {
  const [transport, setTransport] = useState<Transport>("route");
  const [view, setView] = useState<"network" | "page">("page");
  const [run, setRun] = useState<Run | null>(null);
  const [working, setWorking] = useState(false);
  const [unlocked, setUnlocked] = useState(false);

  const select = useCallback((target: Transport) => {
    setTransport(target);
    setRun(null);
    if (target === "action") {
      setUnlocked(true);
    }
  }, []);

  const handleViewChange = useCallback((checked: boolean) => {
    setView(checked ? "network" : "page");
  }, []);

  const armed = nextTransport(transport);

  const viewControls = (
    <div className="flex items-center gap-2.5">
      <label
        className="cursor-pointer select-none font-mono font-semibold text-[0.7rem] text-muted-foreground uppercase tracking-[0.2em]"
        htmlFor="mutation-network-view"
      >
        {VIEW_LABEL}
      </label>
      <Switch
        checked={view === "network"}
        id="mutation-network-view"
        onCheckedChange={handleViewChange}
      />
    </div>
  );

  const deck = (
    <div className="flex flex-wrap items-center gap-3">
      {TRANSPORT_ORDER.map((step, index) => {
        const locked = !(unlocked || step === transport || step === armed);
        return (
          <div className="flex items-center gap-3" key={step}>
            {index > 0 ? (
              <span
                aria-hidden="true"
                className="select-none font-mono text-muted-foreground/50"
              >
                →
              </span>
            ) : null}
            <MarketingButton
              aria-disabled={locked}
              className={cn(LOCKED_LOOK, step === armed && ARMED_LOOK)}
              onClick={() => {
                if (!locked) {
                  select(step);
                }
              }}
              variant="outline"
            >
              <StepMark n={String(index + 1)} />
              {STEP_LABELS[step]}
              <span className="ml-2 font-mono text-muted-foreground text-xs">
                {STEP_DETAILS[step]}
              </span>
            </MarketingButton>
          </div>
        );
      })}
      <span className="ml-auto font-mono text-muted-foreground text-xs tabular-nums">
        {RESULT_CHIP[transport]}
      </span>
    </div>
  );

  return (
    <LivePanel
      deck={deck}
      references={references}
      status={working ? "working" : "live"}
      viewControls={viewControls}
    >
      <div className="flex flex-col gap-5">
        <div className="group/stage grid" data-view={view}>
          <div className={cn("flex flex-col gap-6", PAGE_ONLY)}>
            {specimen}
            <NoteForm
              onRun={setRun}
              onWorking={setWorking}
              transport={transport}
            />
          </div>
          <div className={NETWORK_ONLY}>
            <ExchangeBars run={run} />
          </div>
        </div>
        <p className="font-mono text-muted-foreground text-xs/5">
          {SEAMS[transport]}
        </p>
        <p className="font-mono text-muted-foreground/70 text-xs/5">
          {PUBLIC_DOOR_NOTE}
        </p>
      </div>
    </LivePanel>
  );
}
