export const MUTATION_SOURCE = `
// 1. the endpoint — app/api/press/route.ts
export async function POST(request: NextRequest) {
  const note = checkNote((await request.json()).note);
  if (!note.ok) return NextResponse.json({ error: "..." }, { status: 400 });
  const mark = nextMark(parseMark(request.cookies.get(MARK_COOKIE)?.value), note.value);
  const response = NextResponse.json({ count: mark.count, ok: true });
  response.cookies.set(MARK_COOKIE, serializeMark(mark), { httpOnly: true });
  return response;   // correct, and the page that called it never hears about it
}

