  if (!note.ok) return { ok: false, error: "..." };   // an error, as a value
  const jar = await cookies();
  jar.set(MARK_COOKIE, serializeMark(nextMark(parseMark(jar.get(MARK_COOKIE)?.value), note.value)));
  // Setting a cookie in an action re-renders this page on the server.
  // Nothing below asks for it. That is the whole chapter.
}

// the form — one line different from the one you already write
<form action={saveNote}>
